const flares = $input.all()
  .map(i => i.json)
  .filter(f => f && Object.keys(f).length > 0 && f.flrID);

const start = $now.minus({ days: 7 }).toFormat('yyyy-MM-dd');
const end = $now.toFormat('yyyy-MM-dd');

let html;
if (flares.length === 0) {
  html = '<h2>☀️ NASA Solar Flares</h2>' +
    '<p>No solar flares reported between ' + start + ' and ' + end + '.</p>';
} else {
  const rows = flares.map(f =>
    '<tr>' +
    '<td style="padding:6px 10px;border:1px solid #ddd;">' + (f.classType || '-') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #ddd;">' + (f.beginTime || '-') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #ddd;">' + (f.peakTime || '-') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #ddd;">' + (f.sourceLocation || '-') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #ddd;">' + (f.activeRegionNum || '-') + '</td>' +
    '<td style="padding:6px 10px;border:1px solid #ddd;">' + (f.link ? '<a href="' + f.link + '">details</a>' : '-') + '</td>' +
    '</tr>'
  ).join('');

  html = '<h2>☀️ NASA Solar Flares (' + flares.length + ')</h2>' +
    '<p>Reported between ' + start + ' and ' + end + '.</p>' +
    '<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;">' +
    '<thead><tr>' +
    '<th style="padding:6px 10px;border:1px solid #ddd;background:#f5f5f5;">Class</th>' +
    '<th style="padding:6px 10px;border:1px solid #ddd;background:#f5f5f5;">Begin</th>' +
    '<th style="padding:6px 10px;border:1px solid #ddd;background:#f5f5f5;">Peak</th>' +
    '<th style="padding:6px 10px;border:1px solid #ddd;background:#f5f5f5;">Location</th>' +
    '<th style="padding:6px 10px;border:1px solid #ddd;background:#f5f5f5;">Region</th>' +
    '<th style="padding:6px 10px;border:1px solid #ddd;background:#f5f5f5;">Link</th>' +
    '</tr></thead><tbody>' + rows + '</tbody></table>';
}

return [{ json: { html, count: flares.length, start, end } }];
